import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());

        int limit = 0;
        for (int i = 0; i < n; i++) limit = Math.max(limit, (int) a[i]);
        long[] total = new long[limit + 1];
        for (int i = 0; i < n; i++) total[(int) a[i]] += a[i];
        long take = 0, skip = 0;
        for (int v = 1; v <= limit; v++) {
            long newTake = skip + total[v];
            skip = Math.max(skip, take);
            take = newTake;
        }
        System.out.println(Math.max(take, skip));
    }
}
